Definition f15_only (fr fr' : bvmap 5 word) : Prop := forall r : reg, r <> 15%bv -> reg_get fr' r = reg_get fr r.
Lemma f15_only_refl : forall fr, f15_only fr fr.
Proof.
ltac2:(KReplay.run1 (kr_t_O2LeptKinv ()) ["KinvW"] "h02_Hh12frh21rp;1p;2p;3g0000j10Tg000Uj11Tg001:j12Tg001Xj13Tg002;j2;Tg002gj1:Tg003Ej39Tg003hj35Tg004Bj16Tg004[j27Tg005Ej24Tg005_j28Tg006ZR0#0R1#1#2R2%01#0#0#0#0#2#3R1';%32R3f0R4%10#1#1#:g007?592553#6f2f1'7,41W0W21844eW1o"). Qed.
Lemma f15_only_set : forall fr fr' v, f15_only fr fr' -> f15_only fr (bvmap_set 15 v fr').
Proof.
ltac2:(KReplay.run1 (kr_t_O2LeptKinv ()) ["KinvW"] "h01Hh12Hrh21bh32frh43fr'h51rh61vp;1p;2p;3p;5p;6g0000j10Tg000Uj11Tg001:j16Tg001Xj17Tg002;j2>Tg005_j28Tg002gj1;Tg003Ej33Tg003hj35Tg004Bj1:Tg004[j22Tg007[j54Tg008Kj59Tg009Mj6=Tg009kj2<Tg006ZR0#0R1#1#6R2%01#0#0#0#0#6#7R1'>R3f2R4f1R5'8%72R6f0R7%10#1#1#;R0g007?R8532R9556#:P1f4R6/25f6/249517X21P4P5P7O2P2P1P9f3R:P6D4/25P6P9P5P:P7D9E=W1W5P2P1P81<20d9320P5P4D4,8:eW0X61X43W3o"). Qed.
