(* [comment removed for export] *)
Lemma ki_col : forall k fr cs regs M (j sx rs rd : Z),
  (0 <= j < sx)%Z -> Z.of_nat k = (sx - j)%Z -> (sx < 2 ^ 31)%Z ->
  (4 <= rs)%Z -> (rs + 4 * sx + 4 <= 2 ^ 64)%Z -> (0 <= rd)%Z -> (rd + 4 * sx + 8 <= 2 ^ 64)%Z ->
  (rs + 4 * sx <= rd \/ rd + 4 * sx <= rs)%Z ->
  (forall a, (rs <= a < rs + 4 * sx)%Z -> M (Z_to_bv 64 a) <> None) ->
  store_ok SEGS M (Z_to_bv 64 rd) (Z.to_nat (4 * sx)) = true ->
  getr regs 16 = Z_to_bv 64 (rs + 4 * (sx - 1 - j)) -> getr regs 15 = Z_to_bv 64 (rd + 4 * j) -> getr regs 17 = Z_to_bv 64 (rs - 4) ->
  exists fr' regs' M',
    msteps SEGS (@mkst (mkFP fr cs) regs (0x2cf54 : word) M al_rom) (@mkst (mkFP fr' cs) regs' (0x2cf18 : word) M' al_rom)
    /\ winside rd (rd + 4 * sx) M M' /\ f15_only fr fr'
    /\ regs_agree (fun x => In x [15; 16]%list) regs regs'.
Proof.
