     realizes SEGS (mkCfg (@mkst (mkFP fr' cs) r' (0x2cfdc : word) M' al_rom) (with_vmmaps vm1 md)) S) ->
  realizes SEGS (mkCfg (@mkst (mkFP fr cs) r (0x2cf20 : word) M al_rom) (with_vmmaps vm1 md)) S.
